using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "SharpenFinAction", menuName = "Data/Battle/Battle Actions/Cellarius/SharpenFin Action")]
public class SharpenFinAction : BattleAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private DefaultEffectAction empowerAction;

	[SerializeField]
	private DefaultEffectAction sharpenFinEffectAction;

	[SerializeField]
	private SharpenFinEffect sharpenFinEffect;

	[SerializeField]
	private int sharpenFinAmountToTrigger;

	[SerializeField]
	private int effectAmount;

	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	public PurifyAction PurifyAction => purifyAction;

	public DefaultEffectAction EmpowerAction => empowerAction;

	public DefaultEffectAction SharpenFinEffectAction => sharpenFinEffectAction;

	public SharpenFinEffect SharpenFinEffect => sharpenFinEffect;

	public int SharpenFinAmountToTrigger => sharpenFinAmountToTrigger;

	public int EffectAmount => effectAmount;

	public override void CastTargetAmount(GameObject target, int purifyAmount, GameObject source)
	{
		purifyAction.CastTargetAmount(target, purifyAmount, source);
		UnitEffects component = playerGameObjectReference.value.GetComponent<UnitEffects>();
		if (component.IsEffectActiveGetAmount(sharpenFinEffect) == sharpenFinAmountToTrigger - 1)
		{
			empowerAction.CastTargetAmount(playerGameObjectReference.value, effectAmount, source);
			component.IsEffectActiveRemoveEffect(sharpenFinEffect);
		}
		else
		{
			sharpenFinEffectAction.CastTargetAmount(playerGameObjectReference.value, 1, source);
		}
	}
}
